package com.smarthub.plus;
import android.content.Context;import android.security.keystore.*;import android.util.AtomicFile;import org.json.JSONObject;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.io.*;import java.security.KeyStore;import java.nio.charset.StandardCharsets;import java.util.Arrays;
/** Factory session and user-supplied receiver identity never leave app-private encrypted storage. */
final class FactoryVault {
 private static SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);String alias="iraqhub_factory_session";if(!s.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,3).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build());g.generateKey();}return (SecretKey)s.getKey(alias,null);}
 static synchronized JSONObject read(Context c)throws Exception{File f=new File(c.getFilesDir(),"factory.sealed");if(!f.exists())return new JSONObject();byte[] b=java.nio.file.Files.readAllBytes(f.toPath());if(b.length<30||b.length>65536||b[0]!=12)throw new IOException("FACTORY_STORE_INVALID");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(b,1,13)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(b,13,b.length)),StandardCharsets.UTF_8));}
 static synchronized void save(Context c,JSONObject j)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());AtomicFile f=new AtomicFile(new File(c.getFilesDir(),"factory.sealed"));FileOutputStream out=f.startWrite();try{out.write(12);out.write(cipher.getIV());out.write(cipher.doFinal(j.toString().getBytes(StandardCharsets.UTF_8)));f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}
}
